    """
    Determine whether to retry based on status and error.

    Returns True if retry should be attempted, False otherwise.
    """
    # When status is None, only retry for timeout or connection errors
    if status is None:
        if error == "timeout" or error == "connection":
            return True
        else:
            return False
    else:
        # status is an integer HTTP status code
        if status == 429:
            return True
        if 500 <= status <= 599:
            return True
        # For other 4xx (400-499) or other statuses, do not retry
        return False"}}}]
